// This dump is generated by the actual MongoDB BSON exporter against the
// isolated external fixture. It proves dump/transport behavior, not native
// software installation or an owned database daemon's lifecycle.
func liveDatabaseDumpTransport(t *testing.T, large ...bool) (*core.Service, core.Actor, *Manager, *PrivilegedExecutor, Instance, DatabaseBackup, []byte) {
	t.Helper()
	s, a, m, fixtures := liveDriverFixture(t)
	if len(fixtures["mongodb"]) == 0 {
		t.Skip("set POWERLINUX_MONGO_FIXTURES for a real native BSON dump")
	}
	var in DatabaseRegisterInput
	if json.Unmarshal(fixtures["mongodb"], &in) != nil {
		t.Fatal("invalid isolated MongoDB fixture")
	}
	e := testAgent(t)
	id := "mongodb-transfer"
	instance := Instance{ID: id, PluginID: "mongodb", InstanceID: "transfer", Status: "external-fixture", Paths: e.instancePaths("mongodb", "transfer"), Revision: 1, Ownership: "fixture", Config: map[string]any{"bind": in.Host, "port": in.Port}, Service: ServiceProfile{ID: id, Unit: "powerlinux-plugin-" + id + ".service"}}
	if err := os.MkdirAll(instance.Paths.BackupDir, 0700); err != nil {
		t.Fatal(err)
	}
	if err := e.save("receipts", id, instance); err != nil {
		t.Fatal(err)
	}
	record := managedDatabaseRecord{ManagedDatabase: ManagedDatabase{InstanceID: id, Database: in.Database, Username: in.Username, Engine: "mongodb", Permission: "read_write", State: "active", Revision: 1}, Credential: in.Password}
	if len(large) > 0 && large[0] {
		client, err := openMongoProfile(context.Background(), DatabaseConnection{Engine: "mongodb", Host: in.Host, Port: in.Port, Username: in.Username, Database: in.Database, Access: "database"}, in.Password)
		if err != nil {
			t.Fatal("large dump fixture connection failed")
		}
		name := "qa_stream_" + strconvTime()
		collection := client.Database(in.Database).Collection(name)
		t.Cleanup(func() {
			if err := collection.Drop(context.Background()); err != nil {
				t.Error("large isolated stream collection cleanup failed")
			}
			client.Disconnect(context.Background())
		})
		documents := make([]any, 128)
		for i := range documents {
			documents[i] = bson.D{{Key: "qa_index", Value: i}, {Key: "payload", Value: strings.Repeat("x", 64<<10)}}
		}
		if _, err = collection.InsertMany(context.Background(), documents); err != nil {
			t.Fatal("large isolated stream fixture insert failed")
		}
	}
	backup, err := e.backupManagedDatabase(context.Background(), instance, record)
	if err != nil {
		t.Fatal("native MongoDB BSON dump failed", core.ErrorCode(err))
	}
	data, err := os.ReadFile(filepath.Join(instance.Paths.BackupDir, backup.Filename))
	if err != nil || !bytes.HasPrefix(data, []byte(mongoBackupMagic)) {
		t.Fatal("native dump fixture bytes invalid")
	}
	sum := sha256.Sum256(data)
	if hex.EncodeToString(sum[:]) != backup.SHA256 || len(data) != int(backup.Bytes) {
		t.Fatal("native dump integrity receipt invalid")
	}
	socket := filepath.Join(t.TempDir(), "agent.sock")
	server, err := agent.NewUnixServer(socket, []uint32{uint32(os.Getuid())}, e)
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	t.Cleanup(func() { server.Close() })
	go server.Serve(ctx)
	client, err := agent.NewUnixClient(socket, uint32(os.Getuid()))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { client.Close() })
	m.executor = client
	return s, a, m, e, instance, backup, data
}

type boundedTCPListener struct{ net.Listener }

func (l boundedTCPListener) Accept() (net.Conn, error) {
	conn, err := l.Listener.Accept()
	if err == nil {
		if tcp, ok := conn.(*net.TCPConn); ok {
			_ = tcp.SetWriteBuffer(1024)
		}
	}
	return conn, err
}
func TestLiveNativeDumpHTTPRevocationInterruptsBackpressureWithinLease(t *testing.T) {
	s, a, m, _, instance, backup, _ := liveDatabaseDumpTransport(t, true)
	if backup.Bytes < 8<<20 {
		t.Fatal("real dump did not contain the large isolated fixture")
	}
	api := httpapi.NewWithOptions(s, httpapi.Options{ResourceHandler: m.DatabaseResourceHandler(s)})
	done := make(chan struct{})
	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { defer close(done); api.ServeHTTP(w, r) }))
	server.Listener = boundedTCPListener{server.Listener}
	server.Start()
	defer server.Close()
	token, err := s.CreateToken(context.Background(), a, core.TokenRequest{Name: "leased slow download", Scopes: []string{"databases:backup"}, Resources: []string{DatabaseResource(instance.ID, backup.Database)}})
	if err != nil {
		t.Fatal(err)
	}
	url := server.URL + "/api/v1/databases/backups/download?instance_id=" + instance.ID + "&database=" + backup.Database + "&backup_id=" + backup.ID
	r, _ := http.NewRequest("GET", url, nil)
	r.Header.Set("Authorization", "Bearer "+token.Token)
	response, err := http.DefaultClient.Do(r)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	if response.StatusCode != 200 {
		t.Fatal("large native download failed before backpressure", response.StatusCode)
	}
	started := time.Now()
	if err = s.RevokeToken(context.Background(), a, token.ID); err != nil {
		t.Fatal(err)
	}
	// Do not drain the response: a receiver stalled on data must not keep a
	// revoked private export active until the 30-second write deadline.
	select {
	case <-done:
		if time.Since(started) > 1500*time.Millisecond {
			t.Fatal("download cancellation exceeded its one-second lease")
		}
	case <-time.After(1500 * time.Millisecond):
		t.Fatal("revoked download remained blocked on the receiver")
	}
	bytesRead, copyErr := io.Copy(io.Discard, response.Body)
	if copyErr == nil || bytesRead >= backup.Bytes {
		t.Fatal("revoked download completed instead of aborting its private stream")
	}
}
func TestLiveNativeDumpHTTPFullRangeBoundsAndScopes(t *testing.T) {
	s, a, m, _, instance, backup, data := liveDatabaseDumpTransport(t)
	server := httptest.NewServer(httpapi.NewWithOptions(s, httpapi.Options{ResourceHandler: m.DatabaseResourceHandler(s)}))
	defer server.Close()
	token, err := s.CreateToken(context.Background(), a, core.TokenRequest{Name: "native dump HTTP", Scopes: []string{"databases:backup"}, Resources: []string{DatabaseResource(instance.ID, backup.Database)}})
	if err != nil {
		t.Fatal(err)
	}
	url := server.URL + "/api/v1/databases/backups/download?instance_id=" + instance.ID + "&database=" + backup.Database + "&backup_id=" + backup.ID
	request := func(method, token, byteRange string) (*http.Response, []byte) {
		r, _ := http.NewRequest(method, url, nil)
		r.Header.Set("Authorization", "Bearer "+token)
		if byteRange != "" {
			r.Header.Set("Range", byteRange)
		}
		response, err := http.DefaultClient.Do(r)
		if err != nil {
			t.Fatal(err)
		}
		body, err := io.ReadAll(response.Body)
		response.Body.Close()
		if err != nil {
			t.Fatal("HTTP dump bytes did not complete", err)
		}
		return response, body
	}
	response, body := request("GET", token.Token, "")
	if response.StatusCode != 200 || !bytes.Equal(body, data) || response.ContentLength != backup.Bytes || response.Header.Get("Accept-Ranges") != "bytes" {
		t.Fatal("native HTTP export bytes incorrect")
	}
	response, body = request("HEAD", token.Token, "")
	if response.StatusCode != 200 || len(body) != 0 || response.ContentLength != backup.Bytes {
		t.Fatal("HTTP export HEAD failed")
	}
	for _, spec := range []struct {
		header     string
		start, end int
	}{{"bytes=3-25", 3, 26}, {"bytes=5-", 5, len(data)}, {"bytes=-13", len(data) - 13, len(data)}} {
		response, body = request("GET", token.Token, spec.header)
		if response.StatusCode != 206 || !bytes.Equal(body, data[spec.start:spec.end]) || response.Header.Get("Content-Range") == "" {
			t.Fatal("native HTTP byte range mismatch", spec.header)
		}
	}
	for _, header := range []string{"bytes=999999999-", "bytes=2-1", "bytes=0-1,3-4", "bytes=-0", "bytes=+1-2", "bytes=0-9223372036854775808"} {
		response, body = request("GET", token.Token, header)
		if response.StatusCode != 416 || !strings.HasPrefix(response.Header.Get("Content-Range"), "bytes */") || bytes.Contains(body, []byte(mongoBackupMagic)) {
			t.Fatal("invalid HTTP range exported bytes", header, response.StatusCode)
		}
	}
	other, err := s.CreateToken(context.Background(), a, core.TokenRequest{Name: "other DB", Scopes: []string{"databases:backup"}, Resources: []string{DatabaseResource(instance.ID, "other_db")}})
	if err != nil {
		t.Fatal(err)
	}
	response, body = request("GET", other.Token, "")
	if response.StatusCode != 403 || bytes.Contains(body, []byte(mongoBackupMagic)) {
		t.Fatal("HTTP export crossed database resources")
	}
	software, err := s.CreateToken(context.Background(), a, core.TokenRequest{Name: "software only", Scopes: []string{"backup:manage"}, Resources: []string{"software:" + instance.ID}})
	if err != nil {
		t.Fatal(err)
	}
	response, body = request("GET", software.Token, "")
	if response.StatusCode != 403 || bytes.Contains(body, []byte(mongoBackupMagic)) {
		t.Fatal("generic software scope exported DB bytes")
	}
}

type dumpPATTransport struct{ token string }

func (tr dumpPATTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	r = r.Clone(r.Context())
	r.Header = r.Header.Clone()
	r.Header.Set("Authorization", "Bearer "+tr.token)
	return http.DefaultTransport.RoundTrip(r)
}
func TestLiveNativeDumpMCPChunkHasBoundedBytesAndRevocation(t *testing.T) {
	s, a, _, _, instance, backup, data := liveDatabaseDumpTransport(t)
	token, err := s.CreateToken(context.Background(), a, core.TokenRequest{Name: "native dump MCP", Kind: "mcp", Scopes: []string{"databases:backup"}, Resources: []string{DatabaseResource(instance.ID, backup.Database)}})
	if err != nil {
		t.Fatal(err)
	}
	native, err := mcpbridge.NewHTTP(s, mcpbridge.HTTPOptions{})
	if err != nil {
		t.Fatal(err)
	}
	server := httptest.NewServer(native)
	defer server.Close()
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	client := mcp.NewClient(&mcp.Implementation{Name: "native-db-backup-sdk", Version: "1"}, nil)
	session, err := client.Connect(ctx, &mcp.StreamableClientTransport{Endpoint: server.URL + "/mcp", HTTPClient: &http.Client{Transport: dumpPATTransport{token.Token}}, DisableStandaloneSSE: true, MaxRetries: -1}, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()
	params := map[string]any{"instance_id": instance.ID, "database": backup.Database, "backup_id": backup.ID, "offset": 3, "length": 64 << 10}
	result, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "managed_database_backup_read", Arguments: params})
	if err != nil || result.IsError {
		t.Fatal("MCP native dump chunk failed", err)
	}
	raw, _ := json.Marshal(result.StructuredContent)
	var envelope struct {
		Data struct {
			Data       string `json:"data"`
			NextOffset int64  `json:"next_offset"`
		}
	}
	if json.Unmarshal(raw, &envelope) != nil {
		t.Fatal("MCP chunk response invalid")
	}
	chunk, err := base64.StdEncoding.DecodeString(envelope.Data.Data)
	end := min(len(data), 3+(64<<10))
	if err != nil || !bytes.Equal(chunk, data[3:end]) || envelope.Data.NextOffset != int64(end) {
		t.Fatal("MCP native chunk lost bounded bytes")
	}
	params["length"] = (64 << 10) + 1
	result, err = session.CallTool(ctx, &mcp.CallToolParams{Name: "managed_database_backup_read", Arguments: params})
	if err == nil && !result.IsError {
		t.Fatal("MCP oversized JSON chunk accepted")
	}
	if err = s.RevokeToken(ctx, a, token.ID); err != nil {
		t.Fatal(err)
	}
	if _, err = session.ListTools(ctx, nil); err == nil {
		t.Fatal("MCP revoked lease retained native dump access")
	}
}
